import math
from fractions import Fraction


def ring_cost(P, n, alpha, beta):
    if P < 1:
        raise ValueError('P must be at least 1')
    if n < 0:
        raise ValueError('n must be nonnegative')
    if alpha < 0:
        raise ValueError('alpha must be nonnegative')
    if beta <= 0:
        raise ValueError('beta must be positive')
    if P == 1:
        return Fraction(0), Fraction(0)
    block = Fraction(n, P)
    phases = 2 * (P - 1)
    total = phases * alpha + phases * block / beta
    sent = phases * block
    return total, sent


def ring_cost_loop(P, n, alpha, beta):
    if P < 1:
        raise ValueError('P must be at least 1')
    if n < 0:
        raise ValueError('n must be nonnegative')
    if alpha < 0:
        raise ValueError('alpha must be nonnegative')
    if beta <= 0:
        raise ValueError('beta must be positive')
    if P == 1:
        return Fraction(0), Fraction(0)
    block = Fraction(n, P)
    total = Fraction(0)
    sent = Fraction(0)
    for _stage in range(2):
        for _step in range(P - 1):
            total += alpha
            total += block / beta
            sent += block
    return total, sent


def shared_edge_time(byte_list, capacity):
    total = Fraction(0)
    for b in byte_list:
        total += Fraction(b, capacity)
    return total


def faulty_max_per_flow(byte_list, capacity):
    return max(Fraction(b, capacity) for b in byte_list)


def duplex_time(forward_bytes, reverse_bytes, capacity):
    return max(Fraction(forward_bytes, capacity), Fraction(reverse_bytes, capacity))


def half_duplex_time(forward_bytes, reverse_bytes, capacity):
    return Fraction(forward_bytes + reverse_bytes, capacity)


def route_exists(path, arcs):
    if path is None or len(path) < 2:
        return False
    for i in range(len(path) - 1):
        if (path[i], path[i + 1]) not in arcs:
            return False
    return True


def check_ring_formula():
    GiB = 1024 ** 3
    MiB = 1024 ** 2
    alpha = Fraction(5, 1000000)
    beta = 40 * GiB
    t16, s16 = ring_cost(4, 16 * MiB, alpha, beta)
    t16_ref, s16_ref = ring_cost_loop(4, 16 * MiB, alpha, beta)
    assert t16 == t16_ref
    assert s16 == s16_ref
    assert s16 == Fraction(24 * MiB)
    assert abs(float(t16) * 1000 - 0.6159375) < 1e-12
    t8k, s8k = ring_cost(4, 8 * 1024, alpha, beta)
    assert s8k == Fraction(12 * 1024)
    assert abs(float(t8k) * 1000000 - 30.286102294921875) < 1e-9
    tzero, szero = ring_cost(4, 0, alpha, beta)
    assert tzero == Fraction(30, 1000000)
    assert szero == 0
    assert ring_cost(1, 16 * MiB, alpha, beta) == (Fraction(0), Fraction(0))
    for bad_args in ((0, 1, alpha, beta), (2, -1, alpha, beta), (2, 1, Fraction(-1), beta), (2, 1, alpha, 0)):
        try:
            ring_cost(*bad_args)
        except ValueError:
            pass
        else:
            raise AssertionError('invalid ring arguments were accepted')
    return float(t16) * 1000, float(t8k) * 1000000


def check_shared_edge_negative_control():
    flows = [100, 100]
    good = shared_edge_time(flows, 100)
    bad = faulty_max_per_flow(flows, 100)
    assert good == Fraction(2, 1)
    assert bad == Fraction(1, 1)
    assert bad < good
    return good, bad


def check_direction_and_route():
    d = duplex_time(100, 100, 100)
    h = half_duplex_time(100, 100, 100)
    assert d == Fraction(1, 1)
    assert h == Fraction(2, 1)
    arcs = {('gpu0', 'sw'), ('sw', 'gpu1')}
    assert route_exists(['gpu0', 'sw', 'gpu1'], arcs)
    assert not route_exists(['gpu0', 'gpu1'], arcs)
    assert not route_exists(None, arcs)
    return d, h


def main():
    t16_ms, t8k_us = check_ring_formula()
    print('ring formula: P=4 n=16MiB T_ms =', t16_ms)
    print('ring formula: P=4 n=8KiB T_us =', t8k_us)
    good, bad = check_shared_edge_negative_control()
    print('negative-control rejected: shared-edge good_s =', float(good), 'faulty_max_s =', float(bad))
    d, h = check_direction_and_route()
    print('direction model: full-duplex_s =', float(d), 'half-duplex_s =', float(h))
    print('route model: missing direct arc is rejected')
    print('scope: CPU arithmetic and capacity model only; no GPU, NCCL, NIC, or CUDA execution')


if __name__ == '__main__':
    main()
